function rotatedMinimum(values) {
  let low = 0
  let high = values.length - 1
  while (low < high) {
    const mid = Math.floor((low + high) / 2)
    if (values[mid] > values[high]) low = mid + 1
    else high = mid
  }
  return values[low]
}

